// src/components/Home.js
import React, { useState, useEffect } from 'react';
import { Box, Typography } from '@mui/material';

const Home = () => {
  const [modeData, setModeData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchModeData = async () => {
      try {
        const response = await fetch('https://algori-c.github.io/dss_data/dss_mode.json');
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setModeData(data);
      } catch (err) {
        setError('모드 정보를 가져오는 데 실패했습니다.');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchModeData();
  }, []);

  return (
    <Box 
      sx={{ 
        display: 'flex', 
        flexDirection: 'column', // 이미지와 텍스트를 수직으로 정렬
        justifyContent: 'center', 
        alignItems: 'center', 
        height: '80vh',
        padding: 2
      }}
    >
      <img
        src={process.env.PUBLIC_URL + '/dss.png'}
        alt="DSS"
        style={{ maxWidth: '100%', height: 'auto' }}
      />
      {loading ? (
        <Typography variant="h6" sx={{ mt: 2 }}>
          모드를 로딩 중...
        </Typography>
      ) : error ? (
        <Typography variant="h6" color="error" sx={{ mt: 2 }}>
          {error}
        </Typography>
      ) : (
        <Box sx={{ mt: 2, textAlign: 'center' }}>
          <Typography variant="h6">
            동파법의 주간 모드: {modeData.dss_mode}
          </Typography>
          <Typography variant="subtitle1" color="textSecondary">
            기간: {modeData.start_date} ~ {modeData.end_date}
          </Typography>
        </Box>
      )}
    </Box>
  );
};

export default Home;