import React, { useState, useMemo } from 'react';
import {
  Container,
  Typography,
  TextField,
  Button,
  Grid,
  Paper,
  CircularProgress,
  Checkbox,
  FormControlLabel,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import { styled } from '@mui/system';
import axios from 'axios';
import { LineChart, Line, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';

// 숫자 포맷팅 함수
const formatNumber = (num) => {
    if (num >= 1_000_000_000) {
        return (num / 1_000_000_000).toFixed(1) + 'B';
    } else if (num >= 1_000_000) {
        return (num / 1_000_000).toFixed(1) + 'M';
    } else if (num >= 1_000) {
        return (num / 1_000).toFixed(1) + 'K';
    }
    return num.toString();
};

// Styled components
const FormContainer = styled(Paper)(({ theme }) => ({
    padding: theme.spacing(2),
    [theme.breakpoints.up('sm')]: {
      padding: theme.spacing(4),
    },
    marginTop: theme.spacing(4),
  }));
  
const ResultContainer = styled(Paper)(({ theme }) => ({
    padding: theme.spacing(2),
    [theme.breakpoints.up('sm')]: {
      padding: theme.spacing(4),
    },
    marginTop: theme.spacing(4),
  }));
  
const Backtest = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const [params, setParams] = useState({
    initial_capital: 100000,
    start_date: "2024-01-01",
    end_date: "2024-10-15",
    safe_divisions: 7,
    safe_max_holdings: 30,
    safe_buy_condition: 3.0,
    safe_sell_condition: 0.2,
    aggressive_divisions: 7,
    aggressive_max_holdings: 7,
    aggressive_buy_condition: 5.0,
    aggressive_sell_condition: 2.5,
    capital_update_interval: 10,
    symbol: "SOXL",
    rsi_etf: "QQQ",
    loss_compound_rate: 30.0,
    profit_compound_rate: 80.0,
    commission_rate: 0.044,
    base_index: "SOXX",
    start_withdrawal_rate: 0.0,
    end_withdrawal_rate: 0.0,
    exponential_N: 2,
    withdrawal_T: 250,
    start_T: 0,
    buy_full: false
  });
  
  const [showWithdrawal, setShowWithdrawal] = useState(false); // 새로운 상태 변수 추가
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState(null);
  const [error, setError] = useState(null);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setParams(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : (type === 'number' ? parseFloat(value) : value)
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // 클라이언트 측 유효성 검사 추가
    if (showWithdrawal) {
      if (params.end_withdrawal_rate < params.start_withdrawal_rate) {
        setError("최종 인출률은 초기 인출률보다 작을 수 없습니다.");
        return;
      }
      if (params.end_withdrawal_rate > params.profit_compound_rate) {
        setError("최종 인출률은 이익 복리율보다 클 수 없습니다.");
        return;
      }
    }

    // **투자 기간 유효성 검사 추가**
    const startDate = new Date(params.start_date);
    const endDate = new Date(params.end_date);

    // 날짜 유효성 검사
    if (isNaN(startDate) || isNaN(endDate)) {
      setError("투자 시작일과 종료일이 올바른 날짜 형식이 아닙니다.");
      return;
    }

    // 날짜 차이 계산 (밀리초 단위)
    const diffTime = endDate - startDate;
    const diffDays = diffTime / (1000 * 60 * 60 * 24);

    if (diffDays < 10) {
      setError("투자 종료일은 투자 시작일로부터 최소 10일 이후여야 합니다.");
      return;
    }

    setLoading(true);
    setError(null);
    setResults(null);
  
    const payload = {
      initial_capital: params.initial_capital,
      start_date: params.start_date,
      end_date: params.end_date,
      safe_params: [
        params.safe_divisions,
        params.safe_max_holdings,
        params.safe_buy_condition,
        params.safe_sell_condition
      ],
      aggressive_params: [
        params.aggressive_divisions,
        params.aggressive_max_holdings,
        params.aggressive_buy_condition,
        params.aggressive_sell_condition
      ],
      capital_update_interval: params.capital_update_interval,
      symbol: params.symbol,
      rsi_etf: params.rsi_etf,
      loss_compound_rate: params.loss_compound_rate,
      profit_compound_rate: params.profit_compound_rate,
      commission_rate: params.commission_rate,
      base_index: params.base_index,
      start_withdrawal_rate: showWithdrawal ? params.start_withdrawal_rate : 0,
      end_withdrawal_rate: showWithdrawal ? params.end_withdrawal_rate : 0,
      exponential_N: params.exponential_N,
      withdrawal_T: params.withdrawal_T,
      start_T: params.start_T,
      buy_full: params.buy_full
    };
  
    console.log("Sending payload:", payload);
  
    try {
      const response = await axios.post(
        'https://insangai.com/new_backtest', // Update with your actual endpoint
        payload,
        {
          headers: {
            'Content-Type': 'application/json',
          },
        }
      );
      console.log("Received response:", response.data); // 추가
      setResults(response.data);
    } catch (err) {
      console.error(err);
      setError(err.response ? err.response.data.error : 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleExport = () => {
    if (!results || !results.daily_results) {
      console.error('No results to export');
      return;
    }

    // Reconstruct rows from columnar data
    const { daily_results } = results;
    const keys = Object.keys(daily_results);
    const length = daily_results[keys[0]].length;
    const rows = [];
    for (let i = 0; i < length; i++) {
      const row = {};
      keys.forEach(key => {
        row[key] = daily_results[key][i];
      });
      rows.push(row);
    }

    const ws = XLSX.utils.json_to_sheet(rows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Backtest Results');

    const wbout = XLSX.write(wb, { type: 'array', bookType: 'xlsx' });
    const blob = new Blob([wbout], { type: 'application/octet-stream' });
    saveAs(blob, 'backtest_results.xlsx');
  };

  // Reconstruct rows from columnar data
  const reconstructedDailyResults = useMemo(() => {
    if (!results || !results.daily_results) return [];

    const dailyResults = results.daily_results;
    const keys = Object.keys(dailyResults);
    const length = dailyResults[keys[0]]?.length || 0;

    const rows = [];
    for (let i = 0; i < length; i++) {
      const row = {};
      keys.forEach(key => {
        row[key] = dailyResults[key][i];
      });
      rows.push(row);
    }
    return rows;
  }, [results]);

  // 잉여 현금율 계산 (cash_ratio)
  const processedDailyResults = useMemo(() => {
    if (!reconstructedDailyResults || reconstructedDailyResults.length === 0) return [];

    return reconstructedDailyResults.map(row => {
      const mode = row['Current Mode']; // 가정: 'Current Mode' 필드가 존재
      const divisions = mode === 'safe' ? params.safe_divisions : params.aggressive_divisions;
      const holdings = row['Holdings'] ?? 0; // 가정: 'Holdings' 필드가 존재
      const required_cash = row['Capital'] / divisions * (divisions - holdings);
      const ratio = (row['Cash'] - required_cash) / row['Capital'];
      return {
        ...row,
        cash_ratio: ratio,
      };
    });
  }, [reconstructedDailyResults, params.safe_divisions, params.aggressive_divisions]);

  return (
    <Container 
      sx={{ 
        textAlign: 'center', 
        marginTop: '20px', 
        marginBottom: '20px',
        padding: isMobile ? '0 8px' : '0 24px', // Reduce padding on mobile
      }} 
      maxWidth={isMobile ? false : 'lg'} // Adjust maxWidth based on screen size
    >
      <Typography variant="h4" gutterBottom>
        동파법 백테스트
      </Typography>

      <FormContainer elevation={3}>
        <form onSubmit={handleSubmit}>
          <Grid container spacing={2}>
            {/* 기본 설정 */}
            <Grid item xs={12}>
              <Typography variant="h6">기본 설정</Typography>
            </Grid>
            <Grid item xs={6} sm={4}>
              <TextField
                label="투자종목코드"
                name="symbol"
                value={params.symbol}
                onChange={handleChange}
                fullWidth
                required
                type="text"
              />
            </Grid>
            <Grid item xs={6} sm={4}>
              <TextField
                label="모드변경 RSI 종목"
                name="rsi_etf"
                value={params.rsi_etf}
                onChange={handleChange}
                fullWidth
                required
                type="text"
              />
            </Grid>
            <Grid item xs={6} sm={4}>
              <TextField
                label="기초지수"
                name="base_index"
                value={params.base_index}
                onChange={handleChange}
                fullWidth
                required
                type="text"
              />
            </Grid>

            {/* 투자금 갱신 설정 */}
            <Grid item xs={12}>
              <Typography variant="h6">투자금 갱신 설정</Typography>
            </Grid>
            <Grid item xs={6} sm={4}>
              <TextField
                label="이익복리율 (%) (PCR)"
                name="profit_compound_rate"
                type="number"
                value={params.profit_compound_rate}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 0, step: "0.01" }}
              />
            </Grid>
            <Grid item xs={6} sm={4}>
              <TextField
                label="손실복리율 (%) (LCR)"
                name="loss_compound_rate"
                type="number"
                value={params.loss_compound_rate}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 0, step: "0.01" }}
              />
            </Grid>
            <Grid item xs={6} sm={4}>
              <TextField
                label="투자금갱신주기"
                name="capital_update_interval"
                type="number"
                value={params.capital_update_interval}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 1, step: "1" }}
              />
            </Grid>
            
            {/* 안전모드 설정 */}
            <Grid item xs={12}>
              <Typography variant="h6">안전모드 설정</Typography>
            </Grid>
            <Grid item xs={6} sm={3}>
              <TextField
                label="분할수"
                name="safe_divisions"
                type="number"
                value={params.safe_divisions}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 1, step: "1" }}
              />
            </Grid>
            <Grid item xs={6} sm={3}>
              <TextField
                label="최대보유기간"
                name="safe_max_holdings"
                type="number"
                value={params.safe_max_holdings}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 1, step: "1" }}
              />
            </Grid>
            <Grid item xs={6} sm={3}>
              <TextField
                label="매수조건 (%)"
                name="safe_buy_condition"
                type="number"
                value={params.safe_buy_condition}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 0, step: "0.01" }}
              />
            </Grid>
            <Grid item xs={6} sm={3}>
              <TextField
                label="매도조건 (%)"
                name="safe_sell_condition"
                type="number"
                value={params.safe_sell_condition}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 0, step: "0.01" }}
              />
            </Grid>

            {/* 공세모드 설정 */}
            <Grid item xs={12}>
              <Typography variant="h6">공세모드 설정</Typography>
            </Grid>
            <Grid item xs={6} sm={3}>
              <TextField
                label="분할수"
                name="aggressive_divisions"
                type="number"
                value={params.aggressive_divisions}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 1, step: "1" }}
              />
            </Grid>
            <Grid item xs={6} sm={3}>
              <TextField
                label="최대보유기간"
                name="aggressive_max_holdings"
                type="number"
                value={params.aggressive_max_holdings}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 1, step: "1" }}
              />
            </Grid>
            <Grid item xs={6} sm={3}>
              <TextField
                label="매수조건 (%)"
                name="aggressive_buy_condition"
                type="number"
                value={params.aggressive_buy_condition}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 0, step: "0.01" }}
              />
            </Grid>
            <Grid item xs={6} sm={3}>
              <TextField
                label="매도조건 (%)"
                name="aggressive_sell_condition"
                type="number"
                value={params.aggressive_sell_condition}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 0, step: "0.01" }}
              />
            </Grid>


            {/* TDW 인출 토글 */}
            <Grid item xs={12}>
              <FormControlLabel
                control={
                  <Checkbox
                    checked={showWithdrawal}
                    onChange={(e) => setShowWithdrawal(e.target.checked)}
                    name="showWithdrawal"
                    color="primary"
                  />
                }
                label="TDW 인출"
              />
            </Grid>

            {/* 인출 관련 설정 - 조건부 렌더링 */}
            {showWithdrawal && (
              <>
                <Grid item xs={12}>
                  <Typography variant="h6">인출관련 설정</Typography>
                </Grid>              
                <Grid item xs={12}>
                  <Typography variant="h7">
                    t는 투자금갱신 횟수이며, t 25가 약 1년 입니다. <br />
                    인출 시작이 25이고, 최대인출시점이 250이면 1년 후부터 인출을 시작하여 10년동안 인출률이 높아져서 최종인출률에 도달합니다. 
                  </Typography>
                </Grid>
                <Grid item xs={6} sm={3}>
                  <TextField
                    label="초기인출률 (%)"
                    name="start_withdrawal_rate"
                    type="number"
                    value={params.start_withdrawal_rate}
                    onChange={handleChange}
                    fullWidth
                    required
                    inputProps={{ min: 0, step: "0.01" }}
                  />
                </Grid>
                <Grid item xs={6} sm={3}>
                  <TextField
                    label="최종인출률 (%)"
                    name="end_withdrawal_rate"
                    type="number"
                    value={params.end_withdrawal_rate}
                    onChange={handleChange}
                    fullWidth
                    required
                    inputProps={{ min: 0, step: "0.01" }}
                  />
                </Grid>
                <Grid item xs={6} sm={3}>
                  <TextField
                    label="인출시작시점 (t)"
                    name="start_T"
                    type="number"
                    value={params.start_T}
                    onChange={handleChange}
                    fullWidth
                    required
                    inputProps={{ min: 0, step: "1" }}
                  />
                </Grid>
                <Grid item xs={6} sm={3}>
                  <TextField
                    label="최대인출시점 (T)"
                    name="withdrawal_T"
                    type="number"
                    value={params.withdrawal_T}
                    onChange={handleChange}
                    fullWidth
                    required
                    inputProps={{ min: 1, step: "1" }}
                  />
                </Grid>
                <Grid item xs={6} sm={3}>
                  <TextField
                    label="증가함수지수 (N)"
                    name="exponential_N"
                    type="number"
                    value={params.exponential_N}
                    onChange={handleChange}
                    fullWidth
                    required
                    inputProps={{ min: 1, step: "1" }}
                  />
                </Grid>
              </>
            )}

            {/* 백테스트 설정 */}
            <Grid item xs={12}>
              <Typography variant="h6">백테스트 설정</Typography>
            </Grid>
            <Grid item xs={6} sm={3}>
              <TextField
                label="초기투자금"
                name="initial_capital"
                type="number"
                value={params.initial_capital}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 0, step: "1" }}
              />
            </Grid>
            <Grid item xs={6} sm={3}>
              <TextField
                label="수수료 (%)"
                name="commission_rate"
                type="number"
                value={params.commission_rate}
                onChange={handleChange}
                fullWidth
                required
                inputProps={{ min: 0, step: "0.001" }}
              />
            </Grid>
            <Grid item xs={6} sm={3}>
              <TextField
                label="투자시작일"
                name="start_date"
                type="date"
                value={params.start_date}
                onChange={handleChange}
                fullWidth
                required
                InputLabelProps={{
                  shrink: true,
                }}
              />
            </Grid>
            <Grid item xs={6} sm={3}>
              <TextField
                label="투자종료일"
                name="end_date"
                type="date"
                value={params.end_date}
                onChange={handleChange}
                fullWidth
                required
                InputLabelProps={{
                  shrink: true,
                }}
              />
            </Grid>

            {/* 추가 설정: buy_full */}
            <Grid item xs={12}>
              <Typography variant="h6">추가 설정</Typography>
            </Grid>
            <Grid item xs={12}>
              <FormControlLabel
                control={
                  <Checkbox
                    checked={params.buy_full}
                    onChange={handleChange}
                    name="buy_full"
                    color="primary"
                  />
                }
                label="정액 매수 (추천하지 않습니다)"
              />
            </Grid>

            {/* 제출 버튼 */}
            <Grid item xs={12}>
              <Button
                variant="contained"
                color="primary"
                type="submit"
                disabled={loading}
              >
                {loading ? <CircularProgress size={24} /> : '백테스트 실행'}
              </Button>
            </Grid>
          </Grid>
        </form>
      </FormContainer>

      {/* 오류 메시지 표시 */}
      {error && (
        <ResultContainer elevation={3}>
          <Typography variant="h6" color="error">
            오류 발생: {error}
          </Typography>
        </ResultContainer>
      )}

      {results && (
        <ResultContainer elevation={3}>
            <Typography variant="h5" gutterBottom>
            백테스트 결과
            </Typography>
            <Grid container spacing={2}>
            <Grid item xs={6} sm={6}>
                <Typography variant="subtitle1">
                계좌 평가액: ${results.final_value?.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2}) ?? 'N/A'}
                </Typography>
                <Typography variant="subtitle1">
                계좌 손익: ${results.total_profit?.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2}) ?? 'N/A'}
                </Typography>
                <Typography variant="subtitle1">
                계좌 수익률: {results.total_return_pct?.toFixed(2) ?? 'N/A'}%
                </Typography>
                <Typography variant="subtitle1">
                CAGR: {results.cagr_pct?.toFixed(2) ?? 'N/A'}%
                </Typography>
                <Typography variant="subtitle1">
                최대 낙폭: {results.max_drawdown_pct?.toFixed(2) ?? 'N/A'}%
                </Typography>
                <Typography variant="subtitle1">
                Sortino 비율: {results.sortino_ratio === Infinity ? '∞' : results.sortino_ratio?.toFixed(4) ?? 'N/A'}
                </Typography>
            </Grid>
            <Grid item xs={6} sm={6}>
                <Typography variant="subtitle1">
                실현 손익: ${results.realized_profit?.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2}) ?? 'N/A'}
                </Typography>
                <Typography variant="subtitle1">
                총 인출 금액: ${results.total_withdrawal?.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2}) ?? 'N/A'}
                </Typography>
                <Typography variant="subtitle1">
                불완전 매수 횟수: {results.partial_buy_count?.toLocaleString() ?? 'N/A'}
                </Typography>
                <Typography variant="subtitle1" style={{ fontWeight: 'bold', color: 'blue'  }}>
                (계좌 손익 + 인출금)
                </Typography>
                <Typography variant="subtitle1" style={{ fontWeight: 'bold', color: 'blue'  }}>
                총 손익: ${(results.total_profit + results.total_withdrawal)?.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2}) ?? 'N/A'}
                </Typography>
                <Typography variant="subtitle1" style={{ fontWeight: 'bold', color: 'blue'  }}>
                총 손익률: {(((results.total_profit + results.total_withdrawal) / params.initial_capital) * 100).toFixed(2)}%
                </Typography>
            </Grid>

            {reconstructedDailyResults.length > 0 && (
                <Grid item xs={12}>
                    <Typography variant="h6">동파법 계좌 추이</Typography>
                    <ResponsiveContainer width="100%" height={300}>
                        <LineChart data={reconstructedDailyResults}>
                            <XAxis 
                                dataKey="Date" 
                                tickFormatter={(date) => new Date(date).toLocaleDateString()} 
                            />
                            <YAxis 
                                domain={[0, 'dataMax']}
                                tickFormatter={formatNumber}
                                tick={{ fontSize: 12 }}
                            />
                            <Tooltip 
                                labelFormatter={(date) => new Date(date).toLocaleDateString()} 
                                formatter={(value) => isNaN(value) ? 'N/A' : value.toFixed(2)}
                            />
                            <Legend />
                            <Line type="monotone" dataKey="Current Value" stroke="#8884d8" dot={false} />
                            <Line type="monotone" dataKey="Capital" stroke="#82ca9d" dot={false} />
                            <Line type="monotone" dataKey="Cash" stroke="#ffc658" dot={false} />
                        </LineChart>
                    </ResponsiveContainer>
                </Grid>
            )}

            {/* 잉여 현금율 그래프 - 추가 */}
            {processedDailyResults.length > 0 &&(
                <Grid item xs={12}>
                    <Typography variant="h6">잉여 현금율 (Excess Cash Ratio)</Typography>
                    <ResponsiveContainer width="100%" height={300}>
                        <LineChart data={processedDailyResults}>
                            <XAxis 
                                dataKey="Date" 
                                tickFormatter={(date) => new Date(date).toLocaleDateString()} 
                            />
                            <YAxis 
                                tickFormatter={(value) => (value * 100).toFixed(2) + '%'}
                                tick={{ fontSize: 12 }}
                            />
                            <Tooltip 
                                labelFormatter={(date) => new Date(date).toLocaleDateString()} 
                                formatter={(value) => isNaN(value) ? 'N/A' : `${(value * 100).toFixed(2)}%`}
                            />
                            <Legend />
                            <Line type="monotone" dataKey="cash_ratio" name="잉여 현금율" stroke="#387908" dot={false} />
                        </LineChart>
                    </ResponsiveContainer>
                </Grid>
            )}

            {/* 추가된 부분: TDW 인출이 활성화되었을 때 Realized Profit과 Total Withdrawal 그래프 */}
            {showWithdrawal && reconstructedDailyResults.length > 0 && (
                <Grid item xs={12}>
                    <Typography variant="h6">실현 손익 및 총 인출 금액</Typography>
                    <ResponsiveContainer width="100%" height={300}>
                        <LineChart data={reconstructedDailyResults}>
                            <XAxis 
                                dataKey="Date" 
                                tickFormatter={(date) => new Date(date).toLocaleDateString()} 
                            />
                            <YAxis 
                                tickFormatter={(value) => `$${formatNumber(value)}`} 
                                tick={{ fontSize: 12 }}
                            />
                            <Tooltip 
                                labelFormatter={(date) => new Date(date).toLocaleDateString()} 
                                formatter={(value) => isNaN(value) ? 'N/A' : `$${value.toFixed(2)}`}
                            />
                            <Legend />
                            <Line type="monotone" dataKey="Realized Profit" stroke="#ff7300" dot={false} />
                            <Line type="monotone" dataKey="Total Withdrawal" stroke="#387908" dot={false} />
                        </LineChart>
                    </ResponsiveContainer>
                </Grid>
            )}

            {/* 기존 주석 처리된 최대 낙폭 그래프 (필요시 활성화 가능) */}
            {/* {results.daily_results && results.daily_results.length > 0 && (
                <Grid item xs={12}>
                <Typography variant="h6">최대 낙폭</Typography>
                <ResponsiveContainer width="100%" height={300}>
                    <LineChart data={reconstructedDailyResults}>
                    <XAxis dataKey="Date" tickFormatter={(date) => new Date(date).toLocaleDateString()} />
                    <YAxis />
                    <Tooltip 
                        labelFormatter={(date) => new Date(date).toLocaleDateString()} 
                        formatter={(value) => isNaN(value) ? 'N/A' : value.toFixed(2)}
                    />
                    <Legend />
                    <Line type="monotone" dataKey="Current Drawdown (%)" stroke="#ff7300" dot={false} />
                    </LineChart>
                </ResponsiveContainer>
                </Grid>
            )} */}
            </Grid>

            <Button
            variant="outlined"
            color="secondary"
            onClick={handleExport}
            sx={{ marginTop: '20px' }}
            >
            결과를 엑셀로 저장
            </Button>
        </ResultContainer>
        )}
    </Container>
  );
};

export default Backtest;