// src/components/Calculator.js
import React, { useState } from 'react';
import { 
  Container, 
  Typography, 
  TextField, 
  Button, 
  Box, 
  Grid, 
  Paper, 
  IconButton 
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';

const Calculator = () => {
  const [buyOrder, setBuyOrder] = useState({ type: 'LOC', price: '', quantity: '' });
  const [sellOrders, setSellOrders] = useState([{ type: 'LOC', price: '', quantity: '' }]);
  const [result, setResult] = useState(null);

  const addSellOrder = () => {
    if (sellOrders.length < 10) {
      setSellOrders([...sellOrders, { type: 'LOC', price: '', quantity: '' }]);
    }
  };

  const removeSellOrder = (index) => {
    setSellOrders(sellOrders.filter((_, i) => i !== index));
  };

  const handleBuyChange = (e) => {
    setBuyOrder({ ...buyOrder, [e.target.name]: e.target.value });
  };

  const handleSellChange = (index, e) => {
    const updatedSellOrders = sellOrders.map((order, i) =>
      i === index ? { ...order, [e.target.name]: e.target.value } : order
    );
    setSellOrders(updatedSellOrders);
  };

  const performCalculation = () => {
    // 필드 검증 강화
    const errors = [];
    if (!buyOrder.price || isNaN(buyOrder.price) || parseFloat(buyOrder.price) <= 0) {
      errors.push('매수 주문의 유효한 가격을 입력하세요.');
    }
    if (!buyOrder.quantity || isNaN(buyOrder.quantity) || parseInt(buyOrder.quantity) <= 0) {
      errors.push('매수 주문의 유효한 수량을 입력하세요.');
    }
    sellOrders.forEach((order, index) => {
      if (!order.price && order.type === 'LOC') {
        errors.push(`매도 주문 ${index + 1}의 가격을 입력하세요.`);
      }
      if (!order.quantity || isNaN(order.quantity) || parseInt(order.quantity) <= 0) {
        errors.push(`매도 주문 ${index + 1}의 유효한 수량을 입력하세요.`);
      }
    });
    if (errors.length > 0) {
      alert(errors.join('\n'));
      return;
    }

    const parsedBuyOrder = {
      type: buyOrder.type,
      price: parseFloat(buyOrder.price),
      quantity: parseInt(buyOrder.quantity),
      side: 'BUY'
    };

    const parsedSellOrders = sellOrders.map((order) => ({
      type: order.type,
      price: order.type.includes('LOC') ? parseFloat(order.price) : 0.0,
      quantity: parseInt(order.quantity),
      side: 'SELL'
    }));

    const { newSellOrders, newBuyOrders } = processOrders(parsedBuyOrder, parsedSellOrders);

    setResult({ newSellOrders, newBuyOrders });
  };

  const processOrders = (buy, sells) => {
    let sellOrders = [...sells];
    let buyOrder = { ...buy }; // 구매 주문의 복사본
    const initialBuyQuantity = buyOrder.quantity; // 원래 구매 주문 수량 저장

    let filteredSellOrders = [];
    let newSellOrders = [];
    let newBuyOrders = [];

    let sellMocOrder = null;
    let bExistMoc = false;

    // MOC 주문과 가격이 buy_order.price 이하인 LOC 주문을 분리
    sellOrders.forEach((sellOrder) => {
      if (sellOrder.type === 'MOC') {
        sellMocOrder = sellOrder;
        bExistMoc = true;
      } else if (sellOrder.price <= buyOrder.price) {
        filteredSellOrders.push(sellOrder);
      } else {
        newSellOrders.push(sellOrder);
      }
    });

    // MOC 주문이 없고 필터링된 LOC 주문도 없으면 종료
    if (!bExistMoc && filteredSellOrders.length === 0) {
      return { newSellOrders, newBuyOrders };
    }

    // MOC 주문 처리
    if (bExistMoc) {
      if (sellMocOrder.quantity > buyOrder.quantity) {
        newSellOrders.push({ 
          ...sellMocOrder, 
          quantity: sellMocOrder.quantity - buyOrder.quantity 
        });
        buyOrder.quantity = 0;
      } else if (sellMocOrder.quantity === buyOrder.quantity) {
        buyOrder.quantity = 0;
      } else {
        buyOrder.quantity -= sellMocOrder.quantity;
        if (filteredSellOrders.length === 0) {
          newSellOrders.push({
            type: 'LOC',
            price: parseFloat((buyOrder.price + 0.01).toFixed(2)),
            quantity: sellMocOrder.quantity,
            side: 'SELL'
          });
        }
      }
    }

    // 가격 오름차순으로 정렬
    filteredSellOrders.sort((a, b) => a.price - b.price);

    // 필터링된 LOC 주문 처리
    filteredSellOrders.forEach((sellOrder) => {
      if (buyOrder.quantity === 0) {
        newSellOrders.push(sellOrder);
        return;
      }

      if (sellOrder.quantity >= buyOrder.quantity) {
        const newBuyPrice = parseFloat((sellOrder.price - 0.01).toFixed(2));
        newBuyOrders.push({ 
          type: 'LOC', 
          price: newBuyPrice, 
          quantity: buyOrder.quantity, 
          side: 'BUY' 
        });

        if (sellOrder.quantity > buyOrder.quantity) {
          const newSellQuantity = sellOrder.quantity - buyOrder.quantity;
          newSellOrders.push({ ...sellOrder, quantity: newSellQuantity });
        }
        buyOrder.quantity = 0;
      } else {
        const newBuyPrice = parseFloat((sellOrder.price - 0.01).toFixed(2));
        newBuyOrders.push({ 
          type: 'LOC', 
          price: newBuyPrice, 
          quantity: sellOrder.quantity, 
          side: 'BUY' 
        });
        buyOrder.quantity -= sellOrder.quantity;
      }
    });

    // 남은 구매 주문 처리
    if (buyOrder.quantity !== 0) {
      newBuyOrders.push({ 
        ...buyOrder, 
        price: parseFloat(buyOrder.price.toFixed(2)) 
      });
      const sellQuant = filteredSellOrders.reduce((acc, order) => acc + order.quantity, 0);
      if (sellQuant !== 0) {
        const newSellPrice = parseFloat((buyOrder.price + 0.01).toFixed(2));
        newSellOrders.push({ 
          type: 'LOC', 
          price: newSellPrice, 
          quantity: sellQuant, 
          side: 'SELL' 
        });
      }
    } else {
      // 수정된 부분: 원래 구매 주문 수량을 사용
      const newSellPrice = parseFloat((buyOrder.price + 0.01).toFixed(2));
      newSellOrders.push({ 
        type: 'LOC', 
        price: newSellPrice, 
        quantity: initialBuyQuantity, // 수정된 부분
        side: 'SELL' 
      });
    }

    // 매도 주문 내림차순 정렬
    newSellOrders.sort((a, b) => b.price - a.price);
    // 매수 주문 내림차순 정렬
    newBuyOrders.sort((a, b) => b.price - a.price);

    return { newSellOrders, newBuyOrders };
  };

  return (
    <Container sx={{ px: { xs: 1, sm: 2 }, py: 2 }}>
      <Typography variant="h4" gutterBottom align="center" sx={{ fontSize: { xs: '1.5rem', sm: '2rem' }, marginTop: '10px' }}>
        퉁치기 계산기
      </Typography>
      
      {/* 매수 주문 섹션 */}
      <Paper sx={{ padding: '16px', marginBottom: '20px' }}>
        <Typography variant="h6" gutterBottom sx={{ fontSize: { xs: '1rem', sm: '1.25rem' } }}>
          매수 주문
        </Typography>
        <Grid container spacing={1}>
          <Grid item xs={3} sm={2}>
            <TextField
              label="종류"
              name="type"
              value={buyOrder.type}
              disabled
              fullWidth
              size="small"
              sx={{ 
                '& .MuiInputLabel-root': { fontSize: '0.875rem' }, 
                '& .MuiInputBase-input': { fontSize: '0.875rem' } 
              }}
            />
          </Grid>
          <Grid item xs={3} sm={3}>
            <TextField
              label="가격"
              name="price"
              type="number"
              value={buyOrder.price}
              onChange={handleBuyChange}
              fullWidth
              size="small"
              placeholder="예: 100.50"
              sx={{ 
                '& .MuiInputLabel-root': { fontSize: '0.875rem' }, 
                '& .MuiInputBase-input': { fontSize: '0.875rem' } 
              }}
            />
          </Grid>
          <Grid item xs={3} sm={3}>
            <TextField
              label="수량"
              name="quantity"
              type="number"
              value={buyOrder.quantity}
              onChange={handleBuyChange}
              fullWidth
              size="small"
              placeholder="예: 10"
              sx={{ 
                '& .MuiInputLabel-root': { fontSize: '0.875rem' }, 
                '& .MuiInputBase-input': { fontSize: '0.875rem' } 
              }}
            />
          </Grid>
          <Grid item xs={3} sm={4} display="flex" justifyContent="center" alignItems="center">
          </Grid>
        </Grid>
      </Paper>

      {/* 매도 주문 섹션 */}
      <Paper sx={{ padding: '16px', marginBottom: '20px' }}>
        <Box display="flex" justifyContent="space-between" alignItems="center" mb={1}>
          <Typography variant="h6" sx={{ fontSize: { xs: '1rem', sm: '1.25rem' } }}>
            매도 주문
          </Typography>
          <Button 
            variant="outlined" 
            onClick={addSellOrder} 
            disabled={sellOrders.length >= 10}
            size="small"
            sx={{ 
              fontSize: '0.875rem', 
              paddingX: '8px', 
              paddingY: '4px' 
            }}
          >
            매도 주문 추가
          </Button>
        </Box>
        {sellOrders.map((order, index) => (
          <Grid container spacing={1} key={index} alignItems="center" mb={1}>
            <Grid item xs={3} sm={2}>
              <TextField
                label="종류"
                name="type"
                value={order.type}
                onChange={(e) => handleSellChange(index, e)}
                fullWidth
                select
                SelectProps={{ native: true }}
                size="small"
                sx={{ 
                  '& .MuiInputLabel-root': { fontSize: '0.875rem' }, 
                  '& .MuiInputBase-input': { fontSize: '0.875rem' } 
                }}
              >
                <option value="LOC">LOC</option>
                <option value="MOC">MOC</option>
              </TextField>
            </Grid>
            <Grid item xs={3} sm={3}>
              <TextField
                label="가격"
                name="price"
                type="number"
                value={order.price}
                onChange={(e) => handleSellChange(index, e)}
                fullWidth
                disabled={order.type !== 'LOC'}
                size="small"
                placeholder="예: 101.00"
                sx={{ 
                  '& .MuiInputLabel-root': { fontSize: '0.875rem' }, 
                  '& .MuiInputBase-input': { fontSize: '0.875rem' } 
                }}
              />
            </Grid>
            <Grid item xs={3} sm={3}>
              <TextField
                label="수량"
                name="quantity"
                type="number"
                value={order.quantity}
                onChange={(e) => handleSellChange(index, e)}
                fullWidth
                size="small"
                placeholder="예: 5"
                sx={{ 
                  '& .MuiInputLabel-root': { fontSize: '0.875rem' }, 
                  '& .MuiInputBase-input': { fontSize: '0.875rem' } 
                }}
              />
            </Grid>
            <Grid item xs={3} sm={4} display="flex" justifyContent="center" alignItems="center">
              <IconButton 
                color="error" 
                onClick={() => removeSellOrder(index)}
                aria-label={`삭제 주문 ${index + 1}`}
                size="small"
              >
                <DeleteIcon sx={{ fontSize: '1rem' }} />
              </IconButton>
            </Grid>
          </Grid>
        ))}
      </Paper>

      {/* 계산 버튼 */}
      <Box textAlign="center" mb={4}>
        <Button 
          variant="contained" 
          color="primary" 
          onClick={performCalculation}
          size="large"
          sx={{ 
            fontSize: { xs: '0.875rem', sm: '1rem' }, 
            paddingX: { xs: '16px', sm: '24px' }, 
            paddingY: { xs: '8px', sm: '12px' } 
          }}
        >
          계산하기
        </Button>
      </Box>

      {/* 계산 결과 섹션 */}
      {result && (
        <Paper sx={{ padding: '16px', marginTop: '20px' }}>
          <Typography variant="h6" gutterBottom sx={{ fontSize: { xs: '1rem', sm: '1.25rem' } }}>
            계산 결과
          </Typography>
          <Typography variant="subtitle1" sx={{ fontSize: { xs: '0.875rem', sm: '1rem' } }}>
            새로운 매수 주문:
          </Typography>
          {result.newBuyOrders.length > 0 ? (
            result.newBuyOrders.map((order, index) => (
              <Typography key={index} sx={{ fontSize: { xs: '0.75rem', sm: '0.875rem' }, marginLeft: '8px' }}>
                {order.type} - 가격: {order.price}, 수량: {order.quantity}
              </Typography>
            ))
          ) : (
            <Typography sx={{ fontSize: { xs: '0.875rem', sm: '1rem' }, marginLeft: '8px' }}>없음</Typography>
          )}

          <Typography variant="subtitle1" mt={2} sx={{ fontSize: { xs: '0.875rem', sm: '1rem' } }}>
            새로운 매도 주문:
          </Typography>
          {result.newSellOrders.length > 0 ? (
            result.newSellOrders.map((order, index) => (
              <Typography key={index} sx={{ fontSize: { xs: '0.75rem', sm: '0.875rem' }, marginLeft: '8px' }}>
                {order.type} - 가격: {order.price}, 수량: {order.quantity}
              </Typography>
            ))
          ) : (
            <Typography sx={{ fontSize: { xs: '0.875rem', sm: '1rem' }, marginLeft: '8px' }}>없음</Typography>
          )}
        </Paper>
      )}
    </Container>
  );
};

export default Calculator;